module("word.model", function(require, ...)
local D = require("word.diagnostic")
local math = require("word.host").math
local M = {}
local payload_key = {}

function M.wrap(payload, mt)
    -- Proxy-owned payloads let LuaJIT collect engine/word cycles. A weak-key
    -- registry whose values retain the engine would keep those cycles alive.
    local proxy = newproxy(true)
    local own = getmetatable(proxy)
    for key, value in pairs(mt) do own[key] = value end
    own[payload_key] = payload
    return proxy
end
function M.get(value)
    if type(value) ~= "userdata" then return nil end
    local mt = debug.getmetatable(value)
    return mt and rawget(mt, payload_key)
end
function M.word(value)
    local p = M.get(value)
    return p and p.tag == "word" and p or nil
end
function M.primitive(value)
    local p = M.word(value)
    -- A supplied constructor is a value-producing word, not the primitive type.
    return p and #p.static == 0 and p.definition.primitive or nil
end
function M.source(fn)
    local info = debug.getinfo(fn, "S")
    return info.short_src .. ":" .. info.linedefined
end
function M.plain(value) return type(value) == "table" and getmetatable(value) == nil end

function M.literal(type_word, value)
    local name = M.primitive(type_word)
    if name == "U32" then
        if type(value) ~= "number" then return false end
        local n = math.tointeger(value)
        return n ~= nil and n >= 0 and n <= 0xffffffff, n
    elseif name == "Bool" then
        return type(value) == "boolean", value
    elseif name == "Unit" then
        return value == nil, nil
    end
    return false
end

function M.key(value)
    local p = assert(M.get(value))
    if p.tag == "word" then
        if p.owner or p.occurrence_owner then D.reject("static-required", "Receiver selections are not static cache keys") end
        local parts = { "Word:" .. p.definition.id }
        for _, item in ipairs(p.static) do
            local key = M.key(item); parts[#parts + 1] = #key .. ":" .. key
        end
        return table.concat(parts, ":")
    end
    assert(p.tag == "known")
    local def = M.record(p.type)
    if def then
        local parts = {"Record", M.key(p.type)}
        for _, name in ipairs(def.runtime_order) do
            local key = M.key(p.value[name]); parts[#parts + 1] = #key .. ":" .. key
        end
        return table.concat(parts, ":")
    end
    local name = assert(M.primitive(p.type))
    if name == "Unit" then return "Unit" end
    return name .. ":" .. tostring(p.value)
end

function M.calling_requirement(w)
    local p = M.word(w)
    return p and not M.primitive(w) and p.definition.shape == "ordered" and
        (not p.definition.terminal or #p.static < #p.definition.inputs) or false
end

function M.callable(t)
    local p = M.word(t)
    return p and p.definition.callable
end
-- Compiler-only non-retaining storage references. No source Ref constructor or
-- allocation/lifetime policy is implied by this internal capture representation.
function M.borrow_target(t)
    local p = M.word(t)
    return p and p.definition.borrow_target
end
function M.borrow_type(engine, target)
    engine.borrow_types = engine.borrow_types or {}
    if not engine.borrow_types[target] then
        local def = engine:definition({}, nil)
        def.shape, def.borrow_target = "borrow", target
        engine.borrow_types[target] = engine:handle(def, {})
    end
    return engine.borrow_types[target]
end
function M.record(t)
    local p = M.word(t)
    return p and p.definition.shape == "keyed" and p.definition.sealed and p.definition or nil
end
function M.host_type(t)
    if M.calling_requirement(t) then return true end
    local def = M.record(t)
    if not def then return M.runtime_type(t) end
    for _, name in ipairs(def.runtime_order) do if not M.host_type(def.fields[name]) then return false end end
    return true
end
function M.runtime_type(t, visiting)
    if M.callable(t) then return true end
    local target = M.borrow_target(t)
    if target then return M.record(target) ~= nil and M.runtime_type(target, visiting) end
    local primitive = M.primitive(t)
    if primitive then return primitive == "U32" or primitive == "Bool" or primitive == "Unit" end
    local def = M.record(t)
    if not def then return false end
    visiting = visiting or {}
    if visiting[t] == "done" then return true end
    if visiting[t] then return false end
    visiting[t] = "visiting"
    for _, name in ipairs(def.runtime_order) do
        if not M.runtime_type(def.fields[name], visiting) then visiting[t] = nil; return false end
    end
    visiting[t] = "done" -- Visit shared type subgraphs once, without retaining a cache.
    return true
end

function M.immutable() D.reject("immutable", "Word definitions, specializations, and scalar values are immutable") end


return M

end)

-- word/scope.lua
module("word.scope", function(require, ...)
-- Stable module environments and protected, coroutine-local invocation frames.
local D = require("word.diagnostic")
local table = require("word.host").table
local M = {}
M.__index = M

function M.new()
    return setmetatable({ stacks = setmetatable({}, { __mode = "k" }),
        environments = setmetatable({}, { __mode = "k" }), main_thread = {} }, M)
end
function M:stack()
    local thread = coroutine.running() or self.main_thread
    local stack = self.stacks[thread]
    if not stack then stack = {}; self.stacks[thread] = stack end
    return stack
end
function M:current()
    local stack = self:stack()
    return stack[#stack]
end

function M:find(key, value)
    local stack = self:stack()
    for i = #stack, 1, -1 do if stack[i][key] == value then return stack[i] end end
end
function M:count(key)
    local n = 0
    for _, frame in ipairs(self:stack()) do if frame[key] then n = n + 1 end end
    return n
end

function M:with(frame, action)
    local stack = self:stack()
    local depth = #stack
    local function restore_frames()
        for i = #stack, depth + 1, -1 do stack[i] = nil end
    end
    -- Restore the original depth even when a nested call exits with an error.
    local results = table.pack(xpcall(function()
        stack[depth + 1] = frame
        local values = table.pack(action())
        restore_frames()
        return table.unpack(values, 1, values.n)
    end, function(err)
        restore_frames()
        return err
    end))
    restore_frames()
    if not results[1] then error(D.annotate(results[2], frame.source), 0) end
    return table.unpack(results, 2, results.n)
end

function M:environment(prelude)
    local entries = {}
    for key, value in pairs(prelude) do entries[key] = value end
    local env = setmetatable({}, {
        __index = function(_, key)
            local frame = self:current()
            if frame and frame.lookup_names and frame.terminal == debug.getinfo(2, "f").func then frame.lookup_names[key] = true end
            if frame and frame.has_member and frame.terminal == debug.getinfo(2, "f").func and frame.has_member(key) then
                return frame.read_member(key)
            end
            local value = entries[key]
            if value == nil then D.reject("unknown-name", "Unknown or unavailable module name: " .. tostring(key)) end
            return value
        end,
        __newindex = function(_, key, value)
            local frame = self:current()
            if frame and frame.has_member and frame.terminal == debug.getinfo(2, "f").func and frame.has_member(key) then
                return frame.write_member(key, value)
            end
            D.reject("module-write", "Use a Lua local; module environments are read-only: " .. tostring(key))
        end,
        __metatable = "word module environment",
    })
    self.environments[env] = true
    return env
end

function M:load(source, name, prelude, is_file)
    local env = self:environment(prelude)
    local chunk, err
    if is_file then chunk, err = loadfile(source, "t", env)
    else chunk, err = load(source, name, "t", env) end
    if not chunk then D.reject("lua-load", err) end
    local exports = self:with({ mode = "load", source = name }, chunk)
    if type(exports) ~= "table" or getmetatable(exports) ~= nil then
        D.reject("module-exports", "A DSL module must return a plain Lua export table")
    end
    return exports
end

return M

end)

-- word/ops.lua
module("word.ops", function(require, ...)
local D = require("word.diagnostic")
local Host = require("word.host")
local table, bit = Host.table, Host.bit
local Model = require("word.model")
local M = {}

local function operand(engine, value)
    value = engine:scalar(value)
    local p = Model.get(value)
    if p and p.engine ~= engine then D.reject("foreign-session", "Cannot combine values from different sessions") end
    return value, p
end

function M.binary(engine, op, a, b)
    local pa, pb
    a, pa = operand(engine, a); b, pb = operand(engine, b)
    local t = (pa and pa.type) or (pb and pb.type)
    if t ~= engine.U32 then D.reject("arithmetic-type", "Arithmetic requires U32 operands") end
    a, b = engine:coerce(t, a), engine:coerce(t, b)
    pa, pb = Model.get(a), Model.get(b)
    if (op == "Div" or op == "Mod") and pb.tag == "known" and pb.value == 0 then
        D.reject("division-zero", "U32 quotient and remainder require a nonzero divisor")
    end
    if pa.tag == "known" and pb.tag == "known" then
        local value
        if op == "Add" then value = pa.value + pb.value
        elseif op == "Sub" then value = pa.value - pb.value
        elseif op == "Mul" then value = Host.mul32(pa.value, pb.value)
        elseif op == "Div" then value = math.floor(pa.value / pb.value)
        elseif op == "Mod" then value = pa.value % pb.value
        elseif op == "And" then value = bit.band(pa.value, pb.value)
        elseif op == "Or" then value = bit.bor(pa.value, pb.value)
        elseif op == "Xor" then value = bit.bxor(pa.value, pb.value)
        elseif op == "Shl" then value = pb.value >= 32 and 0 or bit.lshift(pa.value, pb.value)
        elseif op == "Shr" then value = pb.value >= 32 and 0 or bit.rshift(pa.value, pb.value)
        elseif op == "Pow" then
            local base, exponent = pa.value, pb.value; value = 1
            while exponent ~= 0 do
                if exponent % 2 ~= 0 then value = Host.mul32(value, base) end
                exponent = math.floor(exponent / 2); base = Host.mul32(base, base)
            end
        else D.bug("operator", "Unknown arithmetic operation") end
        return engine:known(value % 4294967296, t)
    end
    local builder = engine:context().builder
    return engine:symbol(builder:binary(op, t, engine:reference(a), engine:reference(b)), t, builder)
end

function M.compare(engine, op, a, b)
    local pa, pb
    a, pa = operand(engine, a); b, pb = operand(engine, b)
    local t = (pa and pa.type) or (pb and pb.type)
    if not t or (op ~= "eq" and t ~= engine.U32) then
        D.reject("comparison-type", "Ordered comparison requires U32")
    end
    a, b = engine:coerce(t, a), engine:coerce(t, b)
    pa, pb = Model.get(a), Model.get(b)
    if t ~= engine.U32 and t ~= engine.Bool and t ~= engine.Unit then
        D.reject("comparison-type", "Equality requires scalar operands")
    end
    if pa.tag ~= "known" or pb.tag ~= "known" then
        local context = engine:context()
        if not context or not context.oracle then D.bug("missing-oracle", "Symbolic comparison outside a replay trace") end
        local predicate = context.builder:emit{op = "Compare", type = engine.Bool, operand_type = t,
            predicate = op, args = {engine:reference(a), engine:reference(b)}}
        return context.oracle:choose(predicate)
    end
    if op == "eq" then return pa.value == pb.value end
    if op == "lt" then return pa.value < pb.value end
    return pa.value <= pb.value
end

function M.metatables(engine)
    local operators = {
        __add = function(a, b) return M.binary(engine, "Add", a, b) end,
        __sub = function(a, b) return M.binary(engine, "Sub", a, b) end,
        __mul = function(a, b) return M.binary(engine, "Mul", a, b) end,
        __lt = function(a, b) return M.compare(engine, "lt", a, b) end,
        __le = function(a, b) return M.compare(engine, "le", a, b) end,
        __newindex = Model.immutable,
        __metatable = "immutable word value",
    }
    for name, op in pairs({__div = "Div", __idiv = "Div", __mod = "Mod", __pow = "Pow",
        __band = "And", __bor = "Or", __bxor = "Xor", __shl = "Shl", __shr = "Shr"}) do
        operators[name] = function(a, b) return M.binary(engine, op, a, b) end
    end
    operators.__unm = function(a) return M.binary(engine, "Sub", engine:known(0, engine.U32), a) end
    operators.__bnot = function(a) return M.binary(engine, "Xor", engine:known(0xffffffff, engine.U32), a) end
    -- Explicit adapters for operations this host cannot dispatch on proxies.
    local methods = {}
    for name, op in pairs({band = "And", bor = "Or", bxor = "Xor", shl = "Shl", shr = "Shr", idiv = "Div"}) do
        methods[name] = function(a, b) return M.binary(engine, op, a, b) end
    end
    methods.bnot = operators.__bnot
    methods.lt = function(a, b) return M.compare(engine, "lt", a, b) end
    methods.le = function(a, b) return M.compare(engine, "le", a, b) end
    methods.gt = function(a, b) return M.compare(engine, "lt", b, a) end
    methods.ge = function(a, b) return M.compare(engine, "le", b, a) end
    local word_mt, value_mt = {}, {}
    for key, value in pairs(operators) do word_mt[key] = value; value_mt[key] = value end
    word_mt.__call = function(w, ...) return engine:unpack_result(engine:invoke(w, table.pack(...))) end
    word_mt.__index = function(w, key)
        if key == "of" then return function(target, ...) return engine:specialize(target, table.pack(...)) end end
        if key == "eq" then return function(a, b) return M.compare(engine, "eq", a, b) end end
        if Model.word(w).definition.shape ~= "keyed" and methods[key] then return methods[key] end
        return engine:member(w, key)
    end
    word_mt.__tostring = function(w)
        local p = Model.get(w)
        if p.definition.shape == "keyed" then return "schema#" .. p.definition.id end
        return Model.primitive(w) or ("word#" .. p.definition.id .. "/" .. (#p.definition.inputs - #p.static))
    end
    value_mt.__call = function(v, ...)
        return engine:unpack_result(require("word.callable").invoke(engine, v, table.pack(...)))
    end
    value_mt.__index = function(v, key)
        local p = Model.get(v)
        if p.tag == "known" and Model.record(p.type) then return engine:read_field(v, key) end
        if key == "eq" then return function(a, b) return M.compare(engine, "eq", a, b) end end
        if methods[key] then return methods[key] end
        D.reject("unknown-member", "Unknown scalar member: " .. tostring(key))
    end
    value_mt.__newindex = function(v, key, value)
        if Model.record(Model.get(v).type) then return engine:write_field(v, key, value) end
        Model.immutable()
    end
    value_mt.__tostring = function(v)
        local p = Model.get(v)
        if Model.record(p.type) then return "record-value<" .. tostring(p.type) .. ">" end
        if Model.callable(p.type) then return "callable<" .. tostring(p.type) .. ">" end
        return Model.primitive(p.type) .. "(" .. (p.tag == "known" and tostring(p.value) or ("v" .. p.id)) .. ")"
    end
    local place_mt = {
        __index = function(p, name) return engine:read_field(p, name) end,
        __newindex = function(p, name, value) return engine:write_field(p, name, value) end,
        __tostring = function(p) return "record<" .. tostring(Model.get(p).type) .. ">" end,
        __metatable = "record place",
    }
    return word_mt, value_mt, place_mt
end

return M

end)

-- word/callable.lua
module("word.callable", function(require, ...)
local D = require("word.diagnostic")
local Model = require("word.model")
local Data = require("word.data")
local M = {}

-- An input-only requirement is useful for known code, but cannot describe an
-- unknown runtime call until its result contract has been supplied.
function M.check_results(t, seen)
    if Model.calling_requirement(t) then
        D.reject("callable-result", "Runtime callable result is undetermined; declare results[signature] = ResultType (or a result type list)")
    end
    local def = Model.record(t)
    if not def then return end
    seen = seen or {}; if seen[t] then return end; seen[t] = true
    for _, name in ipairs(def.runtime_order) do M.check_results(def.fields[name], seen) end
end

function M.type(engine, signature, result)
    engine.callable_types = engine.callable_types or {}
    local inputs, parameters, parts = engine:call_inputs(signature), {}, {Model.key(result)}
    for i, t in ipairs(inputs) do
        inputs[i] = engine:requirement_type(t)
        parts[#parts + 1] = Model.key(inputs[i])
    end
    local key = table.concat(parts, "/")
    if engine.callable_types[key] then return engine.callable_types[key] end
    for _, t in ipairs(inputs) do
        M.check_results(t)
        if not Model.runtime_type(t) then D.reject("runtime-type", "Callable input needs a concrete runtime type") end
        if t ~= engine.Unit then parameters[#parameters + 1] = {type = t} end
    end
    local def = engine:definition(inputs, nil)
    local shape = engine:handle(engine:definition(inputs, nil), {})
    def.shape = "callable"; def.callable = {inputs = inputs, parameters = parameters, result = result, signature = shape}
    local t = engine:handle(def, {}); engine.callable_types[key] = t
    return t
end

-- A concrete closure carries its code in its type, not in a runtime function pointer.
function M.infer(engine, value)
    value = require("word.closure").lift(engine, value)
    local graph = engine:context().graph
    local target = graph:require(value, true)
    graph.concrete_callables = graph.concrete_callables or {}
    local t = graph.concrete_callables[target]
    if not t then
        local fn = graph.functions[target]
        local shape = Model.callable(M.type(engine, value, fn.result))
        local def = engine:definition(shape.inputs, nil)
        def.shape = "callable"
        def.callable = {inputs = shape.inputs, parameters = shape.parameters, result = shape.result,
            signature = shape.signature, code = graph:identity(value), environment = fn.receiver and fn.receiver.type,
            value_environment = Model.word(value).definition.capture_fields ~= nil}
        t = Model.wrap({tag = "word", engine = engine, definition = def, static = {}}, engine.word_mt)
        graph.concrete_callables[target] = t
    end
    return M.coerce(engine, t, value)
end

-- A captured borrowed implementation uses an explicit non-retaining interface,
-- including any receiver/capture bundle. Do not pretend that it is owned code.
function M.borrowed(engine, value)
    local p = Model.get(value)
    if p and p.tag == "symbol" and Model.callable(p.type) then
        local abi = Model.callable(p.type)
        if not abi.code then return value end
        return M.coerce(engine, M.type(engine, abi.signature, abi.result), value)
    end
    if p and p.tag == "callable_known" then value = p.code end
    value = require("word.closure").lift(engine, value)
    local graph = engine:context().graph
    local target = graph:require(value, true)
    return M.coerce(engine, M.type(engine, value, graph.functions[target].result), value)
end

local function compatible(a, b)
    if a.result ~= b.result or #a.parameters ~= #b.parameters then return false end
    for i, p in ipairs(a.parameters) do if p.type ~= b.parameters[i].type then return false end end
    return true
end

function M.coerce(engine, t, value)
    local context, p = engine:context(), Model.get(value)
    local abi = Model.callable(t)
    if p and p.tag == "symbol" and Model.callable(p.type) then
        if not context or context.builder ~= p.builder then D.reject("symbol-extent", "Callable escaped its trace") end
        if p.type == t then return value end
        local actual = Model.callable(p.type)
        if not abi.code and actual.code and compatible(abi, actual) then
            local target = context.graph:require(actual.code, true)
            return engine:symbol(context.builder:emit{op = "FunctionRef", type = t, target = target,
                receiver = actual.environment and {closure = p.id, type = actual.environment, by_value = actual.value_environment}}, t, context.builder)
        end
        D.reject("callable-shape", "Callable representations have incompatible signatures or code identities")
    end
    if p and p.tag == "callable_known" then value = p.code end
    value = engine:coerce_callable(abi.signature, value)
    if not context or not context.builder then return value end
    if abi.code then value = require("word.closure").lift(engine, value) end
    if abi.code and context.graph:identity(value) ~= abi.code then D.reject("callable-shape", "Concrete closure code identity mismatch") end
    return Model.wrap({tag = "callable_known", engine = engine, type = t, code = value,
        receiver = Model.word(value).receiver}, engine.value_mt)
end

-- Materialization happens at a data/ABI boundary, never merely because a known word is called.
function M.reference(engine, value)
    local p, context = Model.get(value), engine:context()
    local abi = Model.callable(p.type)
    local code = require("word.closure").lift(engine, p.code)
    local target = context.graph:require(code, true)
    local fn = context.graph.functions[target]
    if not compatible(abi, {result = fn.result, parameters = fn.parameters}) then
        D.reject("callable-shape", "Callable implementation does not match its runtime signature")
    end
    return context.builder:emit{op = "FunctionRef", type = p.type, target = target,
        receiver = fn.receiver and engine:call_receiver(code) or nil, captures = engine:call_captures(code)}
end

function M.invoke(engine, value, args)
    local p = Model.get(value)
    local abi = p and Model.callable(p.type)
    if not abi then D.reject("callable-required", "Value is not a runtime callable") end
    M.coerce(engine, p.type, value)
    if args.n ~= #abi.inputs then D.reject("arity", "Runtime callable arity mismatch") end
    if p.tag == "callable_known" then
        local result = engine:invoke(p.code, args)
        if Model.callable(abi.result) then return M.coerce(engine, abi.result, result) end
        if engine:result_type(result) ~= abi.result then D.reject("callable-shape", "Known callable result does not match its signature") end
        return result
    end
    local operands = {}
    for i, t in ipairs(abi.inputs) do
        local v = engine:coerce(t, args[i])
        if t ~= engine.Unit then operands[#operands + 1] = engine:reference(v) end
    end
    local builder = engine:context().builder
    if abi.code then
        local target = engine:context().graph:require(abi.code, true)
        local receiver = abi.environment and {closure = p.id, type = abi.environment, by_value = abi.value_environment}
        local id = builder:call(abi.result, operands, target, receiver)
        if abi.result == engine.Unit then return engine:known(nil, engine.Unit) end
        local result = engine:symbol(id, abi.result, builder)
        return Model.record(abi.result) and Data.copy(engine, result) or result
    end
    local ins = {op = "IndirectCall", callable = p.id, callable_type = p.type, type = abi.result, args = operands}
    if abi.result == engine.Unit then
        builder:id(); builder.block.instructions[#builder.block.instructions + 1] = ins
        if builder.oracle then builder.oracle:event(ins) end
        return engine:known(nil, engine.Unit)
    end
    local result = engine:symbol(builder:emit(ins), abi.result, builder)
    if Model.record(abi.result) then return Data.copy(engine, result) end
    return result
end

function M.record(engine, t)
    local context = engine:context()
    if not context or not context.graph then return t end
    local cache = context.graph.callable_records or {}
    context.graph.callable_records = cache
    if cache[t] then return cache[t] end
    local def, fields, changed = Model.record(t), {}, false
    for _, name in ipairs(def.order) do
        local ft = def.fields[name]
        fields[name] = def.bindings[name] and ft or engine:requirement_type(ft)
        changed = changed or fields[name] ~= ft
    end
    local result = changed and engine:intern_schema(fields, def.order, def.bindings, def.methods, def.tuple_arity) or t
    cache[t] = result; cache[result] = result
    return result
end

function M.result(engine, requirement)
    local t
    if Model.plain(requirement) then
        local count, n = 0, #requirement
        for key in pairs(requirement) do
            if type(key) ~= "number" or key % 1 ~= 0 or key < 1 or key > n then
                D.reject("result-constraint", "Result type lists must be dense arrays")
            end
            count = count + 1
        end
        if count ~= n then D.reject("result-constraint", "Result type lists must be dense arrays") end
        local fields, order = {}, {}
        for i, value in ipairs(requirement) do
            local name = "r" .. i; fields[name] = engine:requirement_type(value); order[i] = name
        end
        t = n == 0 and engine.Unit or (n == 1 and fields.r1 or engine:intern_schema(fields, order, nil, nil, n))
    else t = engine:requirement_type(requirement) end
    M.check_results(t)
    if not Model.runtime_type(t) then D.reject("runtime-type", "Declared result needs a concrete runtime representation") end
    return t
end

return M

end)

-- word/data.lua
module("word.data", function(require, ...)
-- Runtime record places and immutable snapshots. Value boundaries copy data.
local D = require("word.diagnostic")
local table = require("word.host").table
local Model = require("word.model")
local Borrow = require("word.borrow")
local Owner = require("word.owner")
local M = {}

local function phase(engine)
    local context = engine:context()
    if context and context.mode == "normalize" then
        D.reject("runtime-in-normalization", "Runtime storage cannot be evaluated as static metadata")
    end
    return context
end
local function validate(engine, value)
    local p = Model.get(value)
    if not p or not Model.record(p.type) or
        (p.tag ~= "place" and p.tag ~= "symbol" and p.tag ~= "known") then
        D.reject("type", "Expected a record value")
    end
    if p.engine ~= engine then D.reject("foreign-session", "Record belongs to another session") end
    if p.tag == "known" then engine:check_static(value); return p end
    local context = phase(engine)
    local builder = p.tag == "place" and p.root.builder or p.builder
    if builder then
        if not context or context.builder ~= builder then D.reject("symbol-extent", "Record place escaped its trace") end
    elseif context and context.mode == "residualize" then
        D.reject("runtime-state", "Concrete host storage is not a residual global")
    end
    return p
end
local function wrap(engine, t, root, path)
    root.type = root.type or t
    return Model.wrap({ tag = "place", engine = engine, type = t, root = root, path = path or {} }, engine.place_mt)
end
local function at(p)
    if p.tag == "known" then return p.value end
    local data = p.root.data
    for _, name in ipairs(p.path) do data = data[name] end
    return data
end
local function clone(t, data)
    local def = Model.record(t)
    if not def then return data end -- Scalar values are immutable.
    local p = Model.get(data)
    if p then data = p.value end -- Nested immutable snapshots have typed wrappers.
    local out = {}
    for _, name in ipairs(def.runtime_order) do out[name] = clone(def.fields[name], data[name]) end
    return out
end
local function project(p, name)
    local def = Model.record(p.type)
    local t = def and def.fields[name]
    if not t then D.reject("unknown-field", "Unknown record field: " .. tostring(name)) end
    return t, Owner.extend_path(p.path or p.occurrence_path, name)
end

-- A selected immutable subrecord can retain the lexical occurrence used to
-- reach it without modifying the stored snapshot or its shared definition.
-- The receiver is an actual root when one exists; nil denotes an explicitly
-- unbound schema interface, never an invitation to consult a caller frame.
function M.occurrence(engine, value, owner, receiver, path)
    local p = Model.get(value)
    if not p or p.engine ~= engine or p.tag ~= "known" or not Model.record(p.type) then
        D.bug("snapshot-occurrence", "Expected an immutable record snapshot")
    end
    return Model.wrap({tag = "known", engine = engine, type = p.type, value = p.value,
        record_depth = p.record_depth, record_nodes = p.record_nodes,
        occurrence_owner = owner, occurrence_receiver = receiver,
        occurrence_path = {table.unpack(path or {})}}, engine.value_mt)
end

-- Value/static boundaries copy the snapshot payload, not the lexical route by
-- which it was selected. This is what prevents a detached child from inventing
-- or retaining an outer owner.
function M.detach(engine, value)
    local p = Model.get(value)
    if not p or not p.occurrence_owner then return value end
    local result = engine:known(p.value, p.type)
    local rp = Model.get(result)
    rp.record_depth, rp.record_nodes = p.record_depth, p.record_nodes
    return result
end

local function supply(t, values)
    if not Model.plain(values) then D.reject("keyed-supply", "Record supply requires a plain named table") end
    local def = Model.record(t)
    for name in pairs(values) do
        if not def.fields[name] then D.reject("unknown-field", "Unknown supplied field: " .. tostring(name)) end
        if def.bindings[name] then D.reject("static-field", "Static field is not an input: " .. name) end
    end
    return def
end

-- Contextual conversion, not a runtime constructor or a snapshot of live storage.
function M.constant(engine, t, values, depth)
    depth = depth or 1
    if depth > 32 then D.resource("static-aggregate-depth", "Static aggregate nesting exceeds 32") end
    if Model.word(values) then values = engine:normalize(values) end
    local p = Model.get(values)
    if p then
        if p.engine ~= engine then D.reject("foreign-session", "Static value belongs to another session") end
        if p.tag == "symbol" or p.tag == "place" or p.owner then D.reject("static-required", "Cannot freeze runtime storage") end
        if p.tag ~= "known" or p.type ~= t then D.reject("type", "Expected an immutable record of the declared schema") end
        if depth + p.record_depth - 1 > 32 then D.resource("static-aggregate-depth", "Static aggregate nesting exceeds 32") end
        if p.occurrence_receiver and Model.get(p.occurrence_receiver).tag ~= "known" then
            D.reject("static-required", "Cannot freeze a snapshot selected from runtime storage")
        end
        engine:check_static(values)
        return M.detach(engine, values)
    end
    local def = supply(t, values)
    local fields, height, nodes = {}, 1, 1
    for _, name in ipairs(def.runtime_order) do
        local ft = def.fields[name]
        if values[name] == nil and ft ~= engine.Unit then D.reject("missing-field", "Missing field: " .. name) end
        local value = engine:static_value(ft, values[name], depth + 1)
        fields[name] = value
        local vp = Model.get(value)
        height = math.max(height, 1 + (vp.record_depth or 0))
        nodes = nodes + (vp.record_nodes or 1)
        if nodes > 65536 then D.resource("static-aggregate-size", "Static aggregate exceeds 65536 expanded payload nodes") end
    end
    local result = engine:known(fields, t)
    Model.get(result).record_depth = height
    Model.get(result).record_nodes = nodes
    return result
end

function M.check(engine, t, value)
    if Model.plain(value) then return M.construct(engine, t, value) end
    local p = validate(engine, value)
    if p.type ~= t then D.reject("type", "Record has a different concrete schema") end
    return value
end
function M.reference(engine, value)
    local p = validate(engine, value)
    if p.tag == "symbol" then return p.id end
    if p.tag == "known" then
        local context = phase(engine)
        if not Model.runtime_type(p.type) then D.reject("runtime-type", "Static record has no runtime representation") end
        if not context or not context.builder then D.reject("expected-symbol", "Record materialization needs a builder") end
        local fields = {}
        for _, name in ipairs(Model.record(p.type).runtime_order) do
            if Model.record(p.type).fields[name] ~= engine.Unit then fields[name] = engine:reference(p.value[name]) end
        end
        return context.builder:construct(p.type, fields)
    end
    if not p.root.builder then D.reject("expected-symbol", "Cannot emit host storage") end
    return p.root.builder:load(p.type, p.root.id, p.path)
end
-- Receiver parameters are storage, not by-value record arguments.
function M.receiver(engine, t, builder)
    if not Model.runtime_type(t) then D.reject("runtime-type", "Receiver schema has no runtime storage representation; bind its metadata with :of") end
    return wrap(engine, t, {id = builder:receiver(t), builder = builder})
end
function M.captures(engine, t, builder)
    return wrap(engine, t, {id = builder:captures(t), builder = builder})
end
function M.address(engine, value)
    local p = validate(engine, value)
    if p.tag ~= "place" or not p.root.builder then D.reject("receiver-storage", "A mutable receiver needs residual storage") end
    return {type = p.type, root = p.root.id, path = {table.unpack(p.path)}}
end

-- Capture an actual root, not a by-value snapshot or an inferred parent. The
-- lexical field path stays in code metadata and is reapplied on invocation.
function M.capture_place(engine, value)
    local p = validate(engine, value)
    if p.tag ~= "place" or not p.root.builder then D.reject("receiver-storage", "Captured storage needs a live residual root") end
    local t = Model.borrow_type(engine, p.root.type)
    local id = p.root.builder:emit{op = "Address", type = t, root = p.root.id, path = {}, target_type = p.root.type}
    return engine:symbol(id, t, p.root.builder), {table.unpack(p.path)}
end
function M.restore_place(engine, reference, path)
    local p = Model.get(reference)
    local t = p and Model.borrow_target(p.type)
    if not t then D.bug("capture-reference", "Expected a typed borrowed capture reference") end
    engine:coerce(p.type, reference)
    local builder = engine:context().builder
    local id = builder:emit{op = "Deref", type = t, reference = engine:reference(reference), reference_type = p.type}
    local root = wrap(engine, t, {id = id, builder = builder})
    for _, name in ipairs(path) do root = M.read(engine, root, name) end
    return root
end

function M.copy(engine, value)
    local p = validate(engine, value)
    local context = phase(engine)
    if not (context and context.builder and Model.runtime_type(p.type) or
        not (context and context.builder) and Model.host_type(p.type)) then D.reject("runtime-type", "Record has no runtime representation") end
    if context and context.builder then
        local id = context.builder:local_record(p.type, M.reference(engine, value))
        return wrap(engine, p.type, { id = id, builder = context.builder })
    end
    return wrap(engine, p.type, { data = clone(p.type, at(p)) })
end

local function construct(engine, t, values, captures)
    local context = phase(engine)
    if captures and not (context and context.builder) then D.bug("capture-context", "Capture environments are residual-only") end
    Borrow.check(Borrow.value(engine, t)) -- Methods cannot hide mutable captures outside their record.
    t = engine:as_type(t)
    if not (context and context.builder and Model.runtime_type(t) or
        not (context and context.builder) and Model.host_type(t)) then D.reject("runtime-type", "Record contains static-only fields") end
    local def = supply(t, values)
    local fields = {}
    for _, name in ipairs(def.runtime_order) do
        local ft = def.fields[name]
        if values[name] == nil and ft ~= engine.Unit then D.reject("missing-field", "Missing field: " .. name) end
        local value = engine:coerce(ft, values[name])
        if not captures then Borrow.check(Borrow.value(engine, value)) end
        if context and context.builder then
            if ft ~= engine.Unit then fields[name] = engine:reference(value) end
        elseif Model.record(ft) then fields[name] = clone(ft, at(Model.get(value)))
        else fields[name] = value end
    end
    if context and context.builder then
        local initial = captures and context.builder:emit{op = "Capture", type = t, fields = fields} or
            context.builder:construct(t, fields)
        return wrap(engine, t, { id = context.builder:local_record(t, initial), builder = context.builder })
    end
    return wrap(engine, t, { data = fields })
end

function M.construct(engine, t, values) return construct(engine, t, values, false) end
function M.capture_environment(engine, t, values) return construct(engine, t, values, true) end

function M.read(engine, value, name)
    local p = validate(engine, value)
    local method = Model.record(p.type).methods[name]
    if method then
        local owner, receiver, path
        if p.occurrence_owner then
            owner, receiver, path = p.occurrence_owner, p.occurrence_receiver, p.occurrence_path
        elseif p.tag == "place" and #p.path > 0 then
            owner, receiver, path = p.root.type, wrap(engine, p.root.type, p.root), p.path
        end
        if owner and Owner.needs_outer(p.type, owner, path) then
            return engine:bind_method(method, owner, receiver, path)
        end
        return engine:bind_method(method, p.type, value)
    end
    local t, path = project(p, name)
    local bound = Model.record(p.type).bindings[name]
    if bound then
        if not Model.record(t) then return bound end
        local owner, receiver = p.occurrence_owner, p.occurrence_receiver
        if not owner then
            if p.tag == "place" then owner, receiver = p.root.type, wrap(engine, p.root.type, p.root)
            else owner, receiver = p.type, value end
        end
        return M.occurrence(engine, bound, owner, receiver, path)
    end
    if p.tag == "known" then
        local selected = p.value[name]
        if not Model.record(t) then return selected end
        local owner, receiver
        if p.occurrence_owner then owner, receiver = p.occurrence_owner, p.occurrence_receiver
        else owner, receiver = p.type, value end
        return M.occurrence(engine, selected, owner, receiver, path)
    end
    if Model.record(t) then return wrap(engine, t, p.root, path) end
    if t == engine.Unit then return engine:known(nil, t) end
    if p.root.builder then return engine:symbol(p.root.builder:load(t, p.root.id, path), t, p.root.builder) end
    return at(p)[name] -- A scalar snapshot, not a delayed place read.
end
-- Resolve nearest lexical scope from the selected occurrence's actual root.
-- No inverse pointer arithmetic and no caller-frame lookup is involved.
function M.member_scope(engine, receiver, path, name)
    local scopes = {receiver}
    for _, field in ipairs(path or {}) do scopes[#scopes + 1] = M.read(engine, scopes[#scopes], field) end
    for i = #scopes, 1, -1 do
        local def = Model.record(Model.get(scopes[i]).type)
        if def.fields[name] or def.methods[name] then return scopes[i] end
    end
end

function M.write(engine, value, name, incoming)
    local p = validate(engine, value)
    if Model.record(p.type).methods[name] then D.reject("method-write", "Cannot replace a method: " .. name) end
    local t, path = project(p, name)
    if p.tag == "known" or Model.record(p.type).bindings[name] then
        D.reject("static-field", "Cannot write a static field: " .. name)
    end
    incoming = engine:coerce(t, incoming)
    Borrow.check(Borrow.value(engine, incoming))
    if p.root.builder then
        if t ~= engine.Unit then p.root.builder:store(t, p.root.id, path, engine:reference(incoming)) end
    else
        local snapshot = Model.record(t) and clone(t, at(Model.get(incoming))) or incoming
        at(p)[name] = snapshot
    end
end

function M.unbox(engine, value)
    local p = validate(engine, value)
    if p.tag == "symbol" or (p.root and p.root.builder) then D.reject("expected-known", "Cannot inspect residual storage as a concrete value") end
    local function visit(t, data)
        local def, payload = Model.record(t), Model.get(data)
        if not def then
            if payload.tag == "word" then return data end
            return payload.value
        end
        if payload then data = payload.value end
        local out = {}
        for _, name in ipairs(def.order) do
            out[name] = visit(def.fields[name], def.bindings[name] or data[name])
        end
        return out
    end
    return visit(p.type, at(p))
end

-- Direct embedding operations establish the same protected context as terminal execution.
for _, name in ipairs({ "construct", "copy", "read", "write", "unbox" }) do
    local action = M[name]
    M[name] = function(engine, ...)
        if engine:context() then return action(engine, ...) end
        local args = table.pack(...)
        return engine.scope:with({ context = { mode = "run" } }, function()
            return action(engine, table.unpack(args, 1, args.n))
        end)
    end
end

return M

end)

-- word/borrow.lua
module("word.borrow", function(require, ...)
-- Borrowed callables are local views, never owned result storage.
local Model = require("word.model")
local D = require("word.diagnostic")
local M = {}

function M.type(t)
    if Model.borrow_target(t) then return true end
    local abi = Model.callable(t)
    if abi then return not abi.code or (abi.environment ~= nil and not abi.value_environment) end
    local record = Model.record(t)
    if record then for _, name in ipairs(record.runtime_order) do
        if M.type(record.fields[name]) then return true end
    end end
    return false
end

function M.value(engine, value, seen)
    local p = Model.get(value)
    if not p then return false end
    seen = seen or {}
    if seen[value] then return false end
    seen[value] = true
    if p.tag == "callable_known" then return M.value(engine, p.code, seen) end
    if p.occurrence_receiver and Model.get(p.occurrence_receiver).tag ~= "known" then return true end
    if p.tag == "word" then
        if p.capture_env and M.type(Model.get(p.capture_env).type) then return true end
        if p.definition.borrowed_fields then return true end
        if p.receiver and Model.get(p.receiver).tag ~= "known" and not p.definition.capture_fields then return true end
        local terminal = p.definition.terminal
        if terminal then
            local i = 1
            while true do
                local name, captured = debug.getupvalue(terminal, i)
                if not name then break end
                local cp = Model.get(captured)
                if cp and (cp.tag == "place" or (cp.tag == "symbol" and Model.record(cp.type))) then return true end
                if M.value(engine, captured, seen) then return true end
                i = i + 1
            end
        end
        for _, fields in ipairs({p.definition.fields or {}, p.definition.methods or {}}) do
            for _, child in pairs(fields) do if M.value(engine, child, seen) then return true end end
        end
        return false
    end
    if p.tag == "results" then
        for _, item in ipairs(p.values) do if M.value(engine, item, seen) then return true end end
        return false
    end
    if not M.type(p.type) then return false end
    if p.tag == "symbol" or (p.root and p.root.builder) then return true end
    local record = Model.record(p.type)
    if record then
        local Data = require("word.data")
        for _, name in ipairs(record.runtime_order) do
            if M.value(engine, Data.read(engine, value, name), seen) then return true end
        end
        return false
    end
    return true
end

function M.check(borrowed)
    if borrowed then
        D.reject("borrow-escape", "Borrowed methods/callbacks cannot be returned or stored in records; return the stateful record and select its methods at the call site")
    end
end

-- A local, type-directed check: no ownership graph, output layouts or recursion fixed point.
-- Opaque signatures are borrowed contracts. Foreign implementations must not retain inputs.
function M.verify(program)
    local borrowing_calls = {}
    for _, fn in ipairs(program.functions) do
        local values = {}
        for _, p in ipairs(fn.parameters) do values[p.id] = M.type(p.type) end
        if fn.captures then values[fn.captures.id] = M.type(fn.captures.type) end
        for _, block in ipairs(fn.blocks) do
            for _, ins in ipairs(block.instructions) do
                local borrowed = M.type(ins.type)
                if ins.op == "FunctionRef" then borrowed = ins.captures ~= nil or (ins.receiver ~= nil and not Model.callable(ins.type).value_environment)
                elseif ins.op == "Construct" then
                    for _, id in pairs(ins.fields) do M.check(values[id]) end
                    borrowed = false
                elseif ins.op == "Store" then M.check(values[ins.value])
                elseif ins.op == "Local" then borrowed = values[ins.initial]
                end
                if ins.op == "Call" then
                    if ins.captures and values[ins.captures] then borrowing_calls[ins] = true end
                    for _, id in ipairs(ins.args) do
                        if values[id] then borrowing_calls[ins] = true end
                    end
                end
                if ins.id then values[ins.id] = borrowed end
            end
            if block.exit.op == "Return" then M.check(values[block.exit.value]) end
        end
    end
    return borrowing_calls
end

return M

end)

-- word/owner.lua
module("word.owner", function(require, ...)
-- Lexical member occurrences carried by selections, never mutable parent links
-- on shared definitions. A retained aggregate root is an actual owner binding;
-- a detached value does not acquire one from the dynamic caller.
local Model = require("word.model")
local Host = require("word.host")
local table = Host.table
local M = {}

function M.path_key(path)
    local parts = {}
    for _, name in ipairs(path or {}) do parts[#parts + 1] = #name .. ":" .. name end
    return table.concat(parts, "/")
end

function M.extend_path(path, name)
    local result = {table.unpack(path or {})}
    result[#result + 1] = name
    return result
end

-- Keep the existing immediate-receiver ABI unless this scope (including its
-- children/siblings) can refer to a name supplied by an enclosing occurrence.
-- Conservatively including unused methods keeps recursive sibling calls sound.
function M.needs_outer(t, root_type, path)
    local candidates, owner = {}, root_type
    for _, name in ipairs(path) do
        local def = Model.record(owner)
        for key in pairs(def.fields) do candidates[key] = true end
        for key in pairs(def.methods) do candidates[key] = true end
        owner = def.fields[name]
    end
    local def = Model.record(t)
    for name in pairs(def.fields) do candidates[name] = nil end
    for name in pairs(def.methods) do candidates[name] = nil end
    if not next(candidates) then return false end
    local seen = {}
    local function scan(schema)
        if seen[schema] then return false end; seen[schema] = true
        local record = Model.record(schema)
        if not record then return false end
        for _, method in pairs(record.methods) do
            local terminal = Model.word(method).definition.terminal
            if terminal then
                for name in pairs(Host.environment_names(terminal)) do
                    if candidates[name] then return true end
                end
            end
        end
        for _, field in pairs(record.fields) do if scan(field) then return true end end
        return false
    end
    return scan(t)
end

-- Propagate names along declared field edges only. The type-demand stack is
-- not a lexical chain: an unrelated type demanded inside a factory has no owner.
function M.child_names(parents, fields)
    local names = {}
    for name in pairs(parents or {}) do names[name] = true end
    for name in pairs(fields) do names[name] = true end
    return names
end

return M

end)

-- word/closure.lua
module("word.closure", function(require, ...)
-- Owned and non-retaining capture conversion. Code templates never retain a trace's values.
local Model = require("word.model")
local Data = require("word.data")
local Borrow = require("word.borrow")
local D = require("word.diagnostic")
local M = {}

local function clone(fn)
    return require("word.host").clone(fn)
end
local function static_capture(value, seen)
    local p = Model.get(value)
    if not p then return end
    seen = seen or {}; if seen[value] then return end; seen[value] = true
    if p.tag == "symbol" or p.tag == "place" or p.tag == "callable_known" or
        (p.receiver and Model.get(p.receiver).tag ~= "known") or
        (p.occurrence_receiver and Model.get(p.occurrence_receiver).tag ~= "known") then
        D.reject("capture-type", "Static captured metadata cannot retain runtime values; capture a concrete immutable value instead")
    end
    if p.occurrence_owner then
        static_capture(p.occurrence_owner, seen)
        if p.occurrence_receiver then static_capture(p.occurrence_receiver, seen) end
    end
    if p.tag == "word" then
        local terminal = p.definition.terminal
        if terminal then
            local i = 1
            while true do
                local name, captured = debug.getupvalue(terminal, i)
                if not name then break end
                static_capture(captured, seen); i = i + 1
            end
        end
        for _, fields in ipairs({p.definition.fields or {}, p.definition.methods or {}, p.definition.inputs or {}, p.static}) do
            for _, child in pairs(fields) do static_capture(child, seen) end
        end
    elseif p.tag == "known" and Model.record(p.type) then
        static_capture(p.type, seen)
        for _, child in pairs(p.value) do static_capture(child, seen) end
    end
end
local function token(value)
    local p = Model.get(value)
    if p and p.occurrence_owner then
        local owner, path = Model.key(p.occurrence_owner), require("word.owner").path_key(p.occurrence_path)
        local receiver = p.occurrence_receiver and token(p.occurrence_receiver) or "unbound"
        local payload = Model.key(value)
        return "Occurrence:" .. #owner .. ":" .. owner .. ":" .. #path .. ":" .. path ..
            ":" .. #receiver .. ":" .. receiver .. ":" .. #payload .. ":" .. payload
    end
    if p then return p.owner and p.engine:demand_key(value) or Model.key(value) end
    if type(value) == "number" then return string.format("number:%.17g", value) end
    return type(value) .. ":" .. tostring(value)
end

local function lift(engine, word)
    local p, context = Model.word(word), engine:context()
    if not p or not p.definition.staged or p.definition.capture_fields or p.definition.lexical_fields or p.definition.borrowed_fields then return word end
    local lexical = p.owner and p.definition.lexical_owner and p.receiver
    local borrowed_receiver = lexical and Model.get(p.receiver).tag ~= "known"
    if p.owner and not lexical then return word end
    engine:check_word(word)
    local nodes, visited = {}, {}
    local function visit(value)
        if visited[value] then return visited[value] end
        local wp = Model.word(value)
        local node = {word = value, payload = wp, captures = {}, sort = require("word.host").code(wp.definition.terminal)}
        visited[value] = node; nodes[#nodes + 1] = node; node.ordinal = #nodes
        local i = 1
        while true do
            local name, captured = debug.getupvalue(wp.definition.terminal, i)
            if not name then break end
            local cp = Model.get(captured)
            local slot = {value = captured}
            if lexical and cp and cp.tag == "word" and cp.definition.lexical_owner and
                not cp.definition.lexical_fields and cp.owner == p.owner and cp.receiver == p.receiver then
                slot.link = visit(captured)
            elseif cp and cp.occurrence_receiver and Model.get(cp.occurrence_receiver).tag ~= "known" then
                slot.value, slot.place_path = Data.capture_place(engine, cp.occurrence_receiver)
                for _, field in ipairs(cp.occurrence_path or {}) do
                    slot.place_path[#slot.place_path + 1] = field
                end
                slot.type = Model.get(slot.value).type
            elseif cp and cp.tag == "place" then
                slot.value, slot.place_path = Data.capture_place(engine, captured)
                slot.type = Model.get(slot.value).type
            elseif cp and Borrow.value(engine, captured) and
                (Model.callable(cp.type) or cp.tag == "word" and cp.owner) then
                slot.value = require("word.callable").borrowed(engine, captured)
                slot.type = Model.get(slot.value).type
            elseif not lexical and cp and cp.tag == "word" and cp.definition.staged and cp.definition.terminal and not cp.owner then
                slot.link = visit(captured)
            elseif cp and (cp.tag == "symbol" or cp.tag == "callable_known" or
                (cp.tag == "known" and Model.primitive(cp.type) and cp.type ~= engine.Type) or
                (cp.tag == "word" and (cp.definition.capture_fields or
                    lexical and cp.definition.staged))) then
                if cp.tag == "word" or cp.tag == "callable_known" then
                    captured = require("word.callable").infer(engine, cp.code or captured); cp = Model.get(captured)
                end
                if not Model.runtime_type(cp.type) then
                    D.reject("capture-type", "A capture environment needs concrete runtime types")
                end
                slot.type, slot.value = cp.type, captured
            end
            node.captures[i] = slot; i = i + 1
        end
        return node
    end
    local root = visit(word)
    -- Only recursive code links share an environment. Acyclic captured functions
    -- are ordinary immutable values, whether already materialized or still known.
    local component, changed = {[root] = true}, true
    -- Lexical siblings already share one receiver. Their code links remain
    -- static even when acyclic; capture values and borrowed bindings travel together.
    if lexical then for _, node in ipairs(nodes) do component[node] = true end end
    while changed do
        changed = false
        for _, node in ipairs(nodes) do
            if not component[node] then for _, slot in ipairs(node.captures) do
                if slot.link and component[slot.link] then component[node] = true; changed = true; break end
            end end
        end
    end
    local members = {}
    for _, node in ipairs(nodes) do if component[node] then
        members[#members + 1] = node
        for _, slot in ipairs(node.captures) do
            if slot.link and not component[slot.link] then
                slot.value = require("word.callable").infer(engine, slot.link.word)
                slot.type, slot.link = Model.get(slot.value).type, nil
            end
        end
    end end
    nodes = members
    table.sort(nodes, function(a, b)
        if a.sort == b.sort then return a.ordinal < b.ordinal end
        return a.sort < b.sort
    end)
    for i, node in ipairs(nodes) do node.index = i end
    local fields, order, values, parts, borrowed_values = {}, {}, {}, {}, false
    local function key(s) parts[#parts + 1] = #s .. ":" .. s end
    key(lexical and "lexical" or "owned")
    if lexical then
        key(Model.key(p.owner))
        key(borrowed_receiver and "storage" or Model.key(p.receiver))
    end
    for _, node in ipairs(nodes) do
        if lexical then key(require("word.owner").path_key(node.payload.scope_path)) end
        key(node.sort); key(tostring(getfenv(node.payload.definition.terminal)))
        for _, t in ipairs(node.payload.definition.inputs) do static_capture(t); key(Model.key(t)) end
        key("static")
        for _, v in ipairs(node.payload.static) do static_capture(v); key(token(v)) end
        key("captures")
        for i, slot in ipairs(node.captures) do
            if slot.link then key("link:" .. slot.link.index)
            elseif slot.type then
                local name = "c" .. node.index .. "_" .. i
                slot.field = name; fields[name] = slot.type; order[#order + 1] = name; values[name] = slot.value
                key("field:" .. Model.key(slot.type))
                if slot.place_path then key("place:" .. require("word.owner").path_key(slot.place_path)) end
                borrowed_values = borrowed_values or Borrow.type(slot.type)
            else static_capture(slot.value); key(token(slot.value)) end
        end
    end
    local graph = context.graph
    graph.capture_templates = graph.capture_templates or {}
    local identity = table.concat(parts, "/")
    local group = graph.capture_templates[identity]
    if not group then
        group = {type = engine:intern_schema(fields, order), words = {}, paths = {}}
        for i, node in ipairs(nodes) do
            local original = node.payload.definition
            local terminal = clone(original.terminal)
            local def = engine:definition(original.inputs, terminal)
            def.staged, def.source, def.capture_group = true, original.source, group
            local descriptors = {}
            if lexical and (borrowed_receiver or borrowed_values) then
                def.lexical_fields, def.lexical_owner = descriptors, p.owner
                if #order > 0 then def.lexical_environment = group.type end
                group.paths[i] = node.payload.scope_path
            else
                if borrowed_values then def.borrowed_fields = descriptors
                else def.capture_fields = descriptors end
                if lexical then
                    def.lexical_static = {owner = p.owner, receiver = p.receiver, scope_path = node.payload.scope_path}
                end
            end
            for j, slot in ipairs(node.captures) do
                local descriptor = {field = slot.field, link = slot.link and slot.link.index, place_path = slot.place_path}
                descriptors[j] = descriptor
                -- Only immutable static captures survive in the code template.
                local value = slot.value
                if slot.field or slot.link then value = nil end
                debug.setupvalue(terminal, j, value)
            end
            group.words[i] = engine:handle(def, node.payload.static)
        end
        graph.capture_templates[identity] = group
    end
    local environment
    if #order > 0 then
        environment = (borrowed_values and Data.capture_environment or Data.construct)(engine, group.type, values)
    end
    if lexical and (borrowed_receiver or borrowed_values) then
        return engine:bind_method(group.words[root.index], p.owner, p.receiver, p.scope_path, environment)
    end
    return engine:bind_method(group.words[root.index], group.type, environment)
end

function M.lift(engine, word)
    local scope = engine.scope
    if scope:find("capture_lift", word) then
        D.reject("recursive-result", "A recursively captured implementation needs a grounded callable result before its environment can be materialized")
    end
    if scope:count("capture_lift") >= 32 then D.resource("capture-depth", "Capture conversion nesting exceeds 32") end
    return scope:with({context = engine:context(), capture_lift = word}, function() return lift(engine, word) end)
end

-- Rebind a fresh Lua terminal, not the source closure or any previous trace's upvalues.
function M.instantiate(engine, word)
    local p = Model.word(word)
    local def = p.definition
    local receiver = def.lexical_fields and p.capture_env or p.receiver
    local terminal, expected = clone(def.terminal), {}
    for i, slot in ipairs(def.capture_fields or def.lexical_fields or def.borrowed_fields) do
        local _, value = debug.getupvalue(def.terminal, i)
        if slot.field then
            value = Data.read(engine, receiver, slot.field)
            if slot.place_path then value = Data.restore_place(engine, value, slot.place_path) end
        elseif slot.link then
            if def.lexical_fields then
                value = engine:bind_method(def.capture_group.words[slot.link], p.owner, p.receiver,
                    def.capture_group.paths[slot.link], p.capture_env)
            else value = engine:bind_method(def.capture_group.words[slot.link], p.owner, receiver) end
        end
        debug.setupvalue(terminal, i, value); expected[i] = {value = value}
    end
    return terminal, function()
        for i, item in ipairs(expected) do
            local _, value = debug.getupvalue(terminal, i)
            if not rawequal(value, item.value) then
                D.reject("capture-changed", "A closure cannot reassign a captured binding")
            end
        end
    end
end

-- Outlining must consume converted templates, never construction-trace
-- symbols. All residual source capture kinds are converted above; reaching
-- this check with an unconverted dynamic lexical capture is a compiler error.
function M.check_lexical_outline(word)
    local p = Model.word(word)
    if not p.definition.lexical_owner or p.definition.lexical_fields then return end
    local i = 1
    while true do
        local name, value = debug.getupvalue(p.definition.terminal, i)
        if not name then return end
        local captured = Model.get(value)
        local self_link = captured and captured.definition == p.definition and captured.owner == p.owner
        if captured and not self_link and
            (captured.tag == "symbol" or captured.tag == "place" or captured.tag == "callable_known" or
            (captured.receiver and Model.get(captured.receiver).tag ~= "known")) then
            D.bug("unconverted-capture", "Outlined lexical word still retains a construction-trace capture: " .. name)
        end
        i = i + 1
    end
end

-- A lexical self-call uses this activation's receiver, not the construction trace's place.
function M.lexical(engine, word)
    local p = Model.word(word)
    local terminal, expected, i = clone(p.definition.terminal), {}, 1
    while true do
        local name, value = debug.getupvalue(p.definition.terminal, i)
        if not name then break end
        local captured = Model.word(value)
        if captured and captured.definition == p.definition and captured.owner == p.owner then
            value = engine:bind_method(captured.method, p.owner, p.receiver, p.scope_path)
        end
        debug.setupvalue(terminal, i, value); expected[i] = {value = value}; i = i + 1
    end
    return terminal, function()
        for j, item in ipairs(expected) do
            local _, value = debug.getupvalue(terminal, j)
            if not rawequal(value, item.value) then D.reject("capture-changed", "A lexical word cannot reassign a captured binding") end
        end
    end
end

M.static = static_capture
return M

end)

-- word/ir.lua
module("word.ir", function(require, ...)
local D = require("word.diagnostic")
local Host = require("word.host")
local table, math = Host.table, Host.math
local Model = require("word.model")
local M = {}
local Builder = {}
Builder.__index = Builder

function M.builder(limit, oracle, functions)
    local block = { id = 1, instructions = {} }
    return setmetatable({ fn = { parameters = {}, blocks = { block } }, block = block,
        next_id = 0, limit = limit, constants = {}, oracle = oracle, functions = functions }, Builder)
end
function Builder:id()
    self.next_id = self.next_id + 1
    if self.next_id > self.limit then D.resource("ir-values", "Residual instruction/value budget exhausted") end
    return self.next_id
end
function Builder:receiver(t)
    local id = self:id()
    self.fn.receiver = {id = id, type = t}
    if self.oracle then self.oracle:event{op = "Receiver", id = id, type = t} end
    return id
end
function Builder:captures(t)
    local id = self:id()
    self.fn.captures = {id = id, type = t}
    if self.oracle then self.oracle:event{op = "Captures", id = id, type = t} end
    return id
end
function Builder:parameter(t)
    local id = self:id()
    self.fn.parameters[#self.fn.parameters + 1] = { id = id, type = t }
    if self.oracle then self.oracle:event{op = "Parameter", id = id, type = t} end
    return id
end
function Builder:emit(ins)
    ins.id = self:id(); self.block.instructions[#self.block.instructions + 1] = ins
    if self.oracle then self.oracle:event(ins) end
    return ins.id
end
function Builder:constant(t, value)
    local key = Model.primitive(t) .. ":" .. tostring(value)
    if not self.constants[key] then self.constants[key] = self:emit{ op = "Constant", type = t, value = value } end
    return self.constants[key]
end
function Builder:binary(op, t, a, b) return self:emit{ op = op, type = t, args = { a, b } } end
function Builder:construct(t, fields) return self:emit{ op = "Construct", type = t, fields = fields } end
function Builder:local_record(t, initial) return self:emit{ op = "Local", type = t, initial = initial } end
function Builder:load(t, root, path)
    return self:emit{ op = "Load", type = t, root = root, path = { table.unpack(path) } }
end
function Builder:call(t, args, target, receiver, captures)
    local ins = {op = "Call", target = target or "self", type = t, args = args, receiver = receiver, captures = captures}
    if Model.primitive(t) ~= "Unit" then return self:emit(ins) end
    self:id() -- A void call is still an ordered effect.
    self.block.instructions[#self.block.instructions + 1] = ins
    if self.oracle then self.oracle:event(ins) end
end

function Builder:store(t, root, path, value)
    self:id() -- Stores consume budget even though they define no SSA value.
    local ins = {op = "Store", type = t, root = root, path = { table.unpack(path) }, value = value}
    self.block.instructions[#self.block.instructions + 1] = ins
    if self.oracle then self.oracle:event(ins) end
end
function Builder:finish(t, id)
    self.fn.result = t; self.block.exit = { op = "Return", value = id }
    M.verify_function(self.fn, self.functions)
    return self.fn
end

local function check(ok, message) if not ok then D.bug("invalid-ir", message) end end
local function runtime_value(t) return Model.runtime_type(t) and Model.primitive(t) ~= "Unit" end

function M.verify_function(fn, functions)
    check(type(fn) == "table" and type(fn.parameters) == "table" and
        type(fn.blocks) == "table" and #fn.blocks >= 1, "Expected a function with an entry block")
    check(Model.runtime_type(fn.result), "Unsupported or unsealed result type")
    local defined, all_ids, visited = {}, {}, {}
    local function define(id, t, place)
        check(type(id) == "number" and math.type(id) == "integer" and id > 0 and not all_ids[id], "Invalid value ID")
        all_ids[id] = true
        check(runtime_value(t), "Invalid residual value type")
        defined[id] = { type = t, place = place or false }
    end
    local function value(id, t)
        local entry = defined[id]
        check(entry and not entry.place and entry.type == t, "Operand is undefined, a place, or has the wrong type")
    end
    local function target(ins)
        if ins.closure then
            local entry = defined[ins.closure]
            local abi = entry and Model.callable(entry.type)
            check(abi and abi.code and abi.environment == ins.type and not entry.place and
                not not ins.by_value == not not abi.value_environment, "Invalid concrete closure environment")
            return
        end
        local root = defined[ins.root]
        check(root and root.place and type(ins.path) == "table", "Invalid storage root/path")
        local t = root.type
        for _, name in ipairs(ins.path) do
            local def = Model.record(t)
            check(def and type(name) == "string" and def.fields[name] and not def.bindings[name], "Invalid runtime field path")
            t = def.fields[name]
        end
        check(t == ins.type and runtime_value(t), "Storage path type mismatch")
    end
    if fn.receiver then
        check(type(fn.receiver) == "table" and Model.record(fn.receiver.type), "Receiver requires a record schema")
        define(fn.receiver.id, fn.receiver.type, true)
    end
    if fn.captures then
        check(type(fn.captures) == "table" and Model.record(fn.captures.type), "Captures require a typed environment record")
        define(fn.captures.id, fn.captures.type, true)
    end
    for _, p in ipairs(fn.parameters) do define(p.id, p.type) end
    local function captures(ins, callee)
        if callee.captures then value(ins.captures, callee.captures.type)
        else check(ins.captures == nil, "Unexpected capture argument") end
    end
    local function visit(id, depth)
        check(depth <= 33, "Branch tree exceeds the supported depth")
        local block = fn.blocks[id]
        check(type(block) == "table" and block.id == id and type(block.instructions) == "table" and not visited[id],
            "Invalid block, cycle, or shared suffix in branch tree")
        visited[id] = true
        for _, ins in ipairs(block.instructions) do
            if ins.op == "Constant" then
                check(Model.primitive(ins.type) and Model.literal(ins.type, ins.value), "Malformed typed constant")
            elseif ins.op == "Add" or ins.op == "Sub" or ins.op == "Mul" or ins.op == "Div" or
                ins.op == "Mod" or ins.op == "Pow" or ins.op == "And" or ins.op == "Or" or
                ins.op == "Xor" or ins.op == "Shl" or ins.op == "Shr" then
                check(Model.primitive(ins.type) == "U32" and type(ins.args) == "table" and #ins.args == 2, "Arithmetic type/arity")
                value(ins.args[1], ins.type); value(ins.args[2], ins.type)
            elseif ins.op == "Compare" then
                local t = Model.primitive(ins.operand_type)
                check(Model.primitive(ins.type) == "Bool" and type(ins.args) == "table" and #ins.args == 2 and
                    ((ins.predicate == "eq" and (t == "U32" or t == "Bool")) or
                    ((ins.predicate == "lt" or ins.predicate == "le") and t == "U32")), "Comparison type/arity")
                value(ins.args[1], ins.operand_type); value(ins.args[2], ins.operand_type)
            elseif ins.op == "Construct" or ins.op == "Capture" then
                local def = Model.record(ins.type)
                check(def and type(ins.fields) == "table", "Invalid record construction")
                for name, operand in pairs(ins.fields) do
                    check(def.fields[name] and not def.bindings[name] and Model.primitive(def.fields[name]) ~= "Unit", "Invalid constructor field")
                    value(operand, def.fields[name])
                end
                for _, name in ipairs(def.runtime_order) do
                    if Model.primitive(def.fields[name]) ~= "Unit" then value(ins.fields[name], def.fields[name]) end
                end
            elseif ins.op == "Local" then
                check(Model.record(ins.type), "Local storage requires a record type"); value(ins.initial, ins.type)
            elseif ins.op == "Load" then target(ins)
            elseif ins.op == "Address" then
                check(Model.record(ins.target_type) and Model.borrow_target(ins.type) == ins.target_type,
                    "Invalid captured storage reference type")
                target{root = ins.root, path = ins.path, type = ins.target_type}
            elseif ins.op == "Deref" then
                check(Model.record(ins.type) and Model.borrow_target(ins.reference_type) == ins.type,
                    "Invalid borrowed reference projection")
                value(ins.reference, ins.reference_type)
            elseif ins.op == "FunctionRef" then
                local abi, callee = Model.callable(ins.type), functions and functions[ins.target]
                check(abi and callee and callee.result == abi.result and
                    #callee.parameters == #abi.parameters, "Invalid callable reference")
                if callee.receiver then
                    check(ins.receiver and ins.receiver.type == callee.receiver.type, "Callable environment type mismatch")
                    target(ins.receiver)
                else check(ins.receiver == nil, "Unexpected callable environment") end
                captures(ins, callee)
                check(not callee.captures or not abi.code, "Borrowed capture bundles require a non-retaining callable interface")
                for i, parameter in ipairs(abi.parameters) do
                    check(callee.parameters[i].type == parameter.type, "Callable reference parameter mismatch")
                end
            elseif ins.op == "IndirectCall" then
                local abi = Model.callable(ins.callable_type)
                check(abi and ins.type == abi.result and #ins.args == #abi.parameters, "Invalid indirect call signature")
                value(ins.callable, ins.callable_type)
                for i, parameter in ipairs(abi.parameters) do value(ins.args[i], parameter.type) end
                if Model.primitive(ins.type) == "Unit" then check(ins.id == nil, "Void call defines a value") end
            elseif ins.op == "Call" then
                local callee = fn
                if ins.target ~= "self" then
                    check(math.type(ins.target) == "integer" and ins.target > 0 and functions and functions[ins.target], "Undefined call target")
                    callee = functions[ins.target]
                end
                check(type(callee.parameters) == "table" and ins.type == callee.result and type(ins.args) == "table" and
                    #ins.args == #callee.parameters, "Invalid call result or arity")
                for i, parameter in ipairs(callee.parameters) do value(ins.args[i], parameter.type) end
                if callee.receiver then
                    check(type(ins.receiver) == "table" and Model.record(callee.receiver.type) and
                        ins.receiver.type == callee.receiver.type, "Receiver ABI mismatch")
                    target(ins.receiver)
                else check(ins.receiver == nil, "Unexpected receiver argument") end
                captures(ins, callee)
                if Model.primitive(ins.type) == "Unit" then check(ins.id == nil, "Void call must not define a value") end
            elseif ins.op == "Store" then
                target(ins); value(ins.value, ins.type); check(ins.id == nil, "Store must not define a value")
            else D.bug("invalid-ir", "Unknown residual operation") end
            if ins.op ~= "Store" and not ((ins.op == "Call" or ins.op == "IndirectCall") and Model.primitive(ins.type) == "Unit") then
                define(ins.id, ins.type, ins.op == "Local" or ins.op == "Deref")
            end
        end
        local exit = block.exit
        check(type(exit) == "table", "Missing block exit")
        if exit.op == "Return" then
            if Model.primitive(fn.result) == "Unit" then check(exit.value == nil, "Unit has no runtime payload")
            else value(exit.value, fn.result) end
        elseif exit.op == "Branch" then
            local condition = defined[exit.condition]
            check(condition and not condition.place and Model.primitive(condition.type) == "Bool", "Invalid branch condition")
            visit(exit.yes, depth + 1); visit(exit.no, depth + 1)
        else D.bug("invalid-ir", "Unsupported block exit") end
        for _, ins in ipairs(block.instructions) do if ins.id then defined[ins.id] = nil end end
    end
    visit(1, 1)
    for i, block in ipairs(fn.blocks) do check(block.id == i and visited[i], "Unreachable or misnumbered block") end
    return true
end

function M.verify(program)
    check(type(program) == "table" and type(program.functions) == "table" and type(program.exports) == "table", "Expected program")
    for _, fn in ipairs(program.functions) do M.verify_function(fn, program.functions) end
    local names = {}
    for _, export in ipairs(program.exports) do
        check(type(export.name) == "string" and export.name ~= "" and not names[export.name], "Invalid export name")
        check(program.functions[export.target] ~= nil, "Undefined export target"); names[export.name] = true
    end
    names = {}
    for _, export in ipairs(program.types or {}) do
        check(type(export.name) == "string" and export.name ~= "" and not names[export.name], "Invalid type export name")
        check(Model.runtime_type(export.type), "Type export lacks a runtime representation"); names[export.name] = true
    end
    return true
end

return M

end)

-- word/trace.lua
module("word.trace", function(require, ...)
-- Replay creates fresh traces. Only checked prefixes become shared branch blocks.
local D = require("word.diagnostic")
local table = require("word.host").table
local Model = require("word.model")
local IR = require("word.ir")
local M = {}
local Oracle = {}
Oracle.__index = Oracle

local function equal(a, b)
    if rawequal(a, b) then return true end
    if type(a) ~= "table" or type(b) ~= "table" or Model.get(a) or Model.get(b) then return false end
    for k, v in pairs(a) do if not equal(v, b[k]) then return false end end
    for k in pairs(b) do if a[k] == nil then return false end end
    return true
end

function M.describe(value)
    local p = assert(Model.get(value))
    if p.tag == "results" then
        local values = {}; for i, item in ipairs(p.values) do values[i] = M.describe(item) end
        return {tag = "results", values = values}
    end
    if p.tag == "callable_known" then return {tag = p.tag, type = p.type, code = M.describe(p.code)} end
    if p.tag == "known" and p.occurrence_owner then
        return {tag = "occurrence", type = p.type, key = Model.key(value),
            owner = Model.key(p.occurrence_owner),
            scope_path = require("word.owner").path_key(p.occurrence_path),
            receiver = p.occurrence_receiver and M.describe(p.occurrence_receiver) or nil}
    end
    if p.tag == "word" then
        return {tag = "word", key = Model.key(p.method or value), owner = p.owner,
            scope_path = require("word.owner").path_key(p.scope_path),
            receiver = p.receiver and M.describe(p.receiver) or nil,
            captures = p.capture_env and M.describe(p.capture_env) or nil}
    elseif p.tag == "place" then
        return {tag = "place", type = p.type, root = p.root.id, path = {table.unpack(p.path)}}
    end
    if p.tag == "known" and Model.record(p.type) then
        return {tag = "known", type = p.type, key = Model.key(value)}
    end
    return {tag = p.tag, type = p.type, id = p.id, value = p.value}
end

function Oracle:event(event) self.events[#self.events + 1] = event end
function Oracle:enter(word, arguments)
    local args = {}
    for i, value in ipairs(arguments) do args[i] = M.describe(value) end
    self:event{op = "Enter", word = M.describe(word), args = args}
end
function Oracle:leave(value) self:event{op = "Leave", value = M.describe(value)} end
function Oracle:choose(predicate)
    self.index = self.index + 1
    local entry = self.tape[self.index]
    if entry then
        if not equal(self.events, entry.prefix) then
            D.reject("replay-diverged", "Re-execution changed a previously recorded trace prefix")
        end
        self:event{op = "Decision", predicate = predicate, choice = entry.choice}
        return entry.choice
    end
    if self.index > 32 then D.resource("trace-depth", "Symbolic decision nesting exceeds 32") end
    self.predicate = predicate
    error(self.fork, 0)
end

local function copy(t)
    local out = {}; for k, v in pairs(t) do out[k] = v end; return out
end

-- Result discovery executes only recursion-free prefixes. An unknown call
-- suspends its path; it never supplies a fabricated value to the terminal.
function M.ground(run, blocked, max_paths, other_blocked)
    local paths = 1
    local function visit(tape)
        local oracle = setmetatable({tape = tape, index = 0, events = {}, fork = D.control()}, Oracle)
        local ok, result = pcall(run, oracle)
        local suspended = not ok and (result == blocked or (other_blocked ~= nil and result == other_blocked))
        if not ok and result ~= oracle.fork and not suspended then error(result, 0) end
        if oracle.index < #tape then D.reject("replay-diverged", "Result discovery changed its decision prefix") end
        if ok then return result.result end
        if suspended then return nil end
        paths = paths + 1
        if paths > max_paths then D.resource("trace-paths", "Result discovery path budget exhausted") end
        for _, choice in ipairs({true, false}) do
            local next_tape = copy(tape)
            next_tape[#next_tape + 1] = {choice = choice, prefix = oracle.events}
            local t = visit(next_tape)
            if t then return t end
        end
    end
    return visit({})
end

function M.explore(run, max_paths, max_values, functions)
    local fn = {parameters = {}, blocks = {}}
    local serial, paths = 0, 1
    local function fresh()
        serial = serial + 1
        if serial > max_values then D.resource("ir-values", "Assembled branch tree exceeds the residual budget") end
        return serial
    end
    local function explore(tape, skip, inherited)
        local oracle = setmetatable({tape = tape, index = 0, events = {}, fork = D.control()}, Oracle)
        local ok, result = pcall(run, oracle)
        if not ok and result ~= oracle.fork then error(result, 0) end
        if oracle.index < #tape then D.reject("replay-diverged", "Replay returned before consuming its decision tape") end
        local trace = oracle.builder.fn
        local map = copy(inherited)
        if #tape == 0 then
            if trace.receiver then
                local p = trace.receiver
                map[p.id] = fresh(); fn.receiver = {id = map[p.id], type = p.type}
            end
            if trace.captures then
                local p = trace.captures
                map[p.id] = fresh(); fn.captures = {id = map[p.id], type = p.type}
            end
            for _, p in ipairs(trace.parameters) do
                map[p.id] = fresh(); fn.parameters[#fn.parameters + 1] = {id = map[p.id], type = p.type}
            end
        end
        local function use(id)
            if id == nil then return nil end
            if not map[id] then D.bug("trace-id", "Missing prefix value during trace assembly") end
            return map[id]
        end
        local block = {id = #fn.blocks + 1, instructions = {}}
        fn.blocks[block.id] = block
        local instructions = trace.blocks[1].instructions
        for i = skip + 1, #instructions do
            local ins = instructions[i]
            local out = copy(ins)
            local id = fresh() -- Stores also consume budget.
            if ins.args then
                out.args = {}; for j, operand in ipairs(ins.args) do out.args[j] = use(operand) end
            end
            if ins.fields then
                out.fields = {}; for name, value in pairs(ins.fields) do out.fields[name] = use(value) end
            end
            if ins.callable then out.callable = use(ins.callable) end
            if ins.captures then out.captures = use(ins.captures) end
            if ins.reference then out.reference = use(ins.reference) end
            if ins.initial then out.initial = use(ins.initial) end
            if ins.root then out.root = use(ins.root) end
            if ins.receiver then
                out.receiver = copy(ins.receiver)
                out.receiver.root = use(ins.receiver.root)
                out.receiver.closure = use(ins.receiver.closure)
                out.receiver.path = ins.receiver.path and copy(ins.receiver.path)
            end
            if ins.op == "Store" then out.value = use(ins.value) end
            if ins.id then map[ins.id] = id; out.id = id end
            block.instructions[#block.instructions + 1] = out
        end
        if ok then
            if fn.result and fn.result ~= trace.result then
                D.reject("branch-result", "All residual paths must return the same concrete type")
            end
            fn.result = trace.result
            block.exit = {op = "Return", value = use(trace.blocks[1].exit.value)}
        else
            paths = paths + 1
            if paths > max_paths then D.resource("trace-paths", "Symbolic path budget exhausted") end
            fresh() -- Branches consume the assembled instruction budget too.
            local function arm(choice)
                local next_tape = copy(tape)
                next_tape[#next_tape + 1] = {choice = choice, prefix = oracle.events}
                return explore(next_tape, #instructions, map)
            end
            local yes, no = arm(true), arm(false)
            block.exit = {op = "Branch", condition = use(oracle.predicate), yes = yes, no = no}
        end
        return block.id
    end
    explore({}, 0, {})
    IR.verify_function(fn, functions)
    return fn
end

return M

end)

-- word/c.lua
module("word.c", function(require, ...)
local IR = require("word.ir")
local D = require("word.diagnostic")
local table = require("word.host").table
local Model = require("word.model")
local M = {}

local function escape(name)
    return name:gsub("[^A-Za-z0-9]", function(c) return string.format("_%02x", c:byte()) end)
end
function M.name(name) return "word_" .. escape(name) end
function M.type_name(name) return "wordtype_" .. escape(name) end
function M.result_type_name(name) return "wordresult_" .. escape(name) end
function M.field_name(name) return "f_" .. escape(name) end
local function v(id) return "v" .. id end
local function literal(t, value)
    if Model.primitive(t) == "Bool" then return value and "true" or "false" end
    return "UINT32_C(" .. tostring(value) .. ")"
end

function M.emit(program)
    IR.verify(program)
    local names, order, sizes, serial = {}, {}, {}, 0
    local function ctype(t)
        local primitive = Model.primitive(t)
        if primitive then return assert(({ U32 = "uint32_t", Bool = "bool", Unit = "void" })[primitive]) end
        local borrowed = Model.borrow_target(t)
        if borrowed then return ctype(borrowed) .. " *" end
        if not names[t] then
            serial = serial + 1
            local abi = Model.callable(t)
            names[t] = (abi and (abi.code and "wordclosure_" or "wordcallable_") or "wordrecord_") .. serial
            if abi then
                ctype(abi.result)
                if abi.environment then ctype(abi.environment) end
                for _, p in ipairs(abi.parameters) do ctype(p.type) end
                sizes[t] = 2; order[#order + 1] = t
                return names[t]
            end
            local def = assert(Model.record(t))
            local size = 0
            for _, field in ipairs(def.runtime_order) do
                local ft = def.fields[field]; ctype(ft)
                size = size + (sizes[ft] or (Model.primitive(ft) == "Unit" and 0 or 1))
                if size > 65536 then D.resource("record-layout", "C record layout exceeds 65536 scalar/empty slots") end
            end
            sizes[t] = math.max(1, size)
            order[#order + 1] = t -- By-value children precede their containing structs.
        end
        return names[t]
    end
    for _, export in ipairs(program.types or {}) do ctype(export.type) end
    for _, fn in ipairs(program.functions) do
        ctype(fn.result)
        if fn.receiver then ctype(fn.receiver.type) end
        if fn.captures then ctype(fn.captures.type) end
        for _, p in ipairs(fn.parameters) do ctype(p.type) end
        for _, block in ipairs(fn.blocks) do
            for _, ins in ipairs(block.instructions) do ctype(ins.type) end
        end
    end
    local borrowing_calls = require("word.borrow").verify(program)
    local out = { "/* Generated by the Lua Word DSL. */", "#include <stdint.h>", "#include <stdbool.h>", "#include <stdlib.h>", "" }
    for _, t in ipairs(order) do
        local abi = Model.callable(t)
        if abi and abi.code then
            out[#out + 1] = "typedef struct { " ..
                (abi.environment and (ctype(abi.environment) .. (abi.value_environment and " environment;" or " *environment;")) or "unsigned char word_empty;") ..
                " } " .. ctype(t) .. ";"
        elseif abi then
            local parameters = {"void *"}
            for _, p in ipairs(abi.parameters) do parameters[#parameters + 1] = ctype(p.type) end
            out[#out + 1] = "typedef struct { " .. ctype(abi.result) .. " (*invoke)(" ..
                table.concat(parameters, ", ") .. "); void *environment; } " .. ctype(t) .. ";"
        else
        local def, count = Model.record(t), 0
        out[#out + 1] = "typedef struct {"
        for _, name in ipairs(def.runtime_order) do
            local ft = def.fields[name]
            if Model.primitive(ft) ~= "Unit" then
                out[#out + 1] = "    " .. ctype(ft) .. " " .. M.field_name(name) .. ";"; count = count + 1
            end
        end
        if count == 0 then out[#out + 1] = "    unsigned char word_empty;" end
        out[#out + 1] = "} " .. ctype(t) .. ";"
        end
    end
    for _, export in ipairs(program.types or {}) do
        out[#out + 1] = "typedef " .. ctype(export.type) .. " " .. M.type_name(export.name) .. ";"
    end
    out[#out + 1] = ""
    for _, export in ipairs(program.exports) do
        local t = program.functions[export.target].result
        if Model.callable(t) or (Model.record(t) and Model.record(t).tuple_arity) then
            out[#out + 1] = "typedef " .. ctype(t) .. " " .. M.result_type_name(export.name) .. ";"
        end
    end
    local pointer_roots = {}
    for _, fn in ipairs(program.functions) do
        local roots = {}; pointer_roots[fn] = roots
        if fn.receiver then roots[fn.receiver.id] = true end
        for _, block in ipairs(fn.blocks) do for _, ins in ipairs(block.instructions) do
            if ins.op == "Deref" then roots[ins.id] = true end
        end end
    end
    local function target(ins, fn)
        if ins.closure then return "(" .. (ins.by_value and "" or "*") .. v(ins.closure) .. ".environment)" end
        local path = pointer_roots[fn][ins.root] and ("(*" .. v(ins.root) .. ")") or v(ins.root)
        for _, name in ipairs(ins.path) do path = path .. "." .. M.field_name(name) end
        return path
    end
    local function_names, reachable, definitions = {}, {}, {}
    local function visit(id)
        if reachable[id] then return end
        reachable[id] = true
        for _, block in ipairs(program.functions[id].blocks) do
            for _, ins in ipairs(block.instructions) do
                if (ins.op == "Call" and ins.target ~= "self") or ins.op == "FunctionRef" then visit(ins.target) end
            end
        end
    end
    for _, export in ipairs(program.exports) do
        function_names[export.target] = function_names[export.target] or M.name(export.name)
        definitions[#definitions + 1] = {target = export.target, name = M.name(export.name), storage = ""}
        visit(export.target)
    end
    for _, id in pairs(program.callable_targets or {}) do visit(id) end
    for id in ipairs(program.functions) do
        if reachable[id] and not function_names[id] then
            function_names[id] = "wordfn_" .. id
            definitions[#definitions + 1] = {target = id, name = function_names[id], storage = "static "}
        end
    end
    local function header(definition)
        local fn, parameters = program.functions[definition.target], {}
        if fn.receiver then parameters[#parameters + 1] = ctype(fn.receiver.type) .. " *" .. v(fn.receiver.id) end
        if fn.captures then parameters[#parameters + 1] = ctype(fn.captures.type) .. " " .. v(fn.captures.id) end
        for _, p in ipairs(fn.parameters) do parameters[#parameters + 1] = ctype(p.type) .. " " .. v(p.id) end
        return definition.storage .. ctype(fn.result) .. " " .. definition.name .. "(" ..
            (#parameters > 0 and table.concat(parameters, ", ") or "void") .. ")"
    end
    for _, definition in ipairs(definitions) do out[#out + 1] = header(definition) .. ";" end
    -- Borrowed callback bundles live in the caller's activation: an actual
    -- receiver pointer plus immutable captures copied by value, never a heap.
    local function bundle(id) return "wordbound_" .. id end
    for id, fn in ipairs(program.functions) do
        if reachable[id] and fn.captures then
            out[#out + 1] = "typedef struct { " ..
                (fn.receiver and (ctype(fn.receiver.type) .. " *receiver; ") or "") ..
                ctype(fn.captures.type) .. " captures; } " .. bundle(id) .. ";"
        end
    end
    local adapters = {}
    local function adapter(ins) return "wordadapter_" .. ins.target .. "_" .. ctype(ins.type) end
    for id, fn in ipairs(program.functions) do
        if reachable[id] then for _, block in ipairs(fn.blocks) do for _, ins in ipairs(block.instructions) do
            if ins.op == "FunctionRef" and not Model.callable(ins.type).code and not adapters[adapter(ins)] then
                adapters[adapter(ins)] = true
                local abi, parameters, args = Model.callable(ins.type), {"void *environment"}, {}
                local callee = program.functions[ins.target]
                if callee.receiver then
                    args[#args + 1] = callee.captures and ("((" .. bundle(ins.target) .. " *)environment)->receiver") or
                        ("(" .. ctype(callee.receiver.type) .. " *)environment")
                end
                if callee.captures then args[#args + 1] = "((" .. bundle(ins.target) .. " *)environment)->captures" end
                for i, p in ipairs(abi.parameters) do
                    parameters[#parameters + 1] = ctype(p.type) .. " a" .. i; args[#args + 1] = "a" .. i
                end
                out[#out + 1] = "static " .. ctype(abi.result) .. " " .. adapter(ins) .. "(" .. table.concat(parameters, ", ") ..
                    ") { (void)environment; " .. (Model.primitive(abi.result) == "Unit" and "" or "return ") ..
                    function_names[ins.target] .. "(" .. table.concat(args, ", ") .. "); }"
            end
        end end end
    end
    local function closure_api(name, t, seen, internal)
        local abi = Model.callable(t)
        if not abi or not abi.code then return end
        local id = program.callable_targets[t]
        local parameters, args = {}, {}
        parameters[#parameters + 1] = ctype(t) .. " closure"
        if abi.environment then args[#args + 1] = (abi.value_environment and "&" or "") .. "closure.environment" end
        for i, p in ipairs(abi.parameters) do
            parameters[#parameters + 1] = ctype(p.type) .. " a" .. i; args[#args + 1] = "a" .. i
        end
        out[#out + 1] = ctype(abi.result) .. (internal and " wordcalltype_" or " wordcall_") .. name .. "(" ..
            table.concat(parameters, ", ") .. ") { (void)closure; " ..
            (Model.primitive(abi.result) == "Unit" and "" or "return ") .. function_names[id] ..
            "(" .. table.concat(args, ", ") .. "); }"
        if not internal and Model.callable(abi.result) then
            out[#out + 1] = "typedef " .. ctype(abi.result) .. " wordresult_call_" .. name .. ";"
            seen = seen or {}; seen[t] = true
            if not seen[abi.result] then closure_api(name .. "_result", abi.result, seen) end
        end
    end
    for _, t in ipairs(order) do closure_api(ctype(t), t, nil, true) end
    for _, export in ipairs(program.exports) do
        local t = program.functions[export.target].result
        closure_api(escape(export.name), t)
        local record = Model.record(t)
        if record then for _, name in ipairs(record.runtime_order) do
            closure_api(escape(export.name) .. "_" .. escape(name), record.fields[name])
        end end
    end
    out[#out + 1] = ""
    for _, definition in ipairs(definitions) do
        local fn = program.functions[definition.target]
        out[#out + 1] = header(definition)
        out[#out + 1] = "{"
        if fn.receiver then out[#out + 1] = "    (void)" .. v(fn.receiver.id) .. ";" end
        if fn.captures then out[#out + 1] = "    (void)" .. v(fn.captures.id) .. ";" end
        for _, p in ipairs(fn.parameters) do out[#out + 1] = "    (void)" .. v(p.id) .. ";" end
        local function tail_call(block)
            if block.exit.op ~= "Return" then return nil end
            local instructions = block.instructions
            local index = #instructions
            while index > 0 and instructions[index].op ~= "Call" do index = index - 1 end
            local last = instructions[index]
            if not last or last.target ~= "self" or borrowing_calls[last] then return nil end
            -- Keep the exact incoming receiver; never replace it with caller-local storage.
            if fn.receiver and (last.receiver.root ~= fn.receiver.id or #last.receiver.path ~= 0) then return nil end
            if index == #instructions and block.exit.value == last.id then return last, index end
            if not Model.record(last.type) then return nil end
            -- Record returns can forward through copies, projections and exact reconstruction.
            -- Every post-call operand must originate in that return; stores/calls/arithmetic forbid rewriting.
            local origins = {[last.id] = {path = {}}}
            local function project(node, name)
                if not node then return nil end
                if node.path then
                    local path = {table.unpack(node.path)}; path[#path + 1] = name
                    return {path = path}
                end
                return node.fields[name]
            end
            for i = index + 1, #instructions do
                local ins, node = instructions[i]
                if ins.op == "Local" then node = origins[ins.initial]
                elseif ins.op == "Load" then
                    node = origins[ins.root]
                    for _, name in ipairs(ins.path) do node = project(node, name) end
                elseif ins.op == "Construct" then
                    node = {fields = {}}
                    for name, id in pairs(ins.fields) do
                        if not origins[id] then return nil end
                        node.fields[name] = origins[id]
                    end
                else return nil end
                if not node then return nil end
                origins[ins.id] = node
            end
            local function unchanged(node, t, path)
                if not node then return false end
                if node.path then
                    if #node.path ~= #path then return false end
                    for i, name in ipairs(path) do if node.path[i] ~= name then return false end end
                    return true
                end
                local def = Model.record(t)
                if not def then return false end
                for _, name in ipairs(def.runtime_order) do
                    local ft = def.fields[name]
                    if Model.primitive(ft) ~= "Unit" then
                        local child = {table.unpack(path)}; child[#child + 1] = name
                        if not unchanged(node.fields[name], ft, child) then return false end
                    end
                end
                return true
            end
            if unchanged(origins[block.exit.value], last.type, {}) then return last, index end
        end
        local looping = false
        for _, block in ipairs(fn.blocks) do if tail_call(block) then looping = true end end
        local function call(ins)
            local args = {}
            if ins.receiver then args[#args + 1] = "&(" .. target(ins.receiver, fn) .. ")" end
            if ins.captures then args[#args + 1] = v(ins.captures) end
            for _, id in ipairs(ins.args) do args[#args + 1] = v(id) end
            if ins.op == "IndirectCall" then
                table.insert(args, 1, v(ins.callable) .. ".environment")
                return v(ins.callable) .. ".invoke(" .. table.concat(args, ", ") .. ")"
            end
            local name = ins.target == "self" and definition.name or function_names[ins.target]
            return name .. "(" .. table.concat(args, ", ") .. ")"
        end
        local function emit_block(id, indent)
            local block = fn.blocks[id]
            local tail, tail_index = tail_call(block)
            for i = 1, (tail_index or (#block.instructions + 1)) - 1 do
                local ins = block.instructions[i]
                if ins.op == "Pow" then
                    local base, exponent, result = "wordbase_" .. ins.id, "wordexp_" .. ins.id, v(ins.id)
                    out[#out + 1] = indent .. "uint32_t " .. result .. " = UINT32_C(1);"
                    out[#out + 1] = indent .. "uint32_t " .. base .. " = " .. v(ins.args[1]) .. ", " .. exponent .. " = " .. v(ins.args[2]) .. ";"
                    out[#out + 1] = indent .. "while (" .. exponent .. " != 0) {"
                    out[#out + 1] = indent .. "    if ((" .. exponent .. " & UINT32_C(1)) != 0) " .. result ..
                        " = (uint32_t)((uint64_t)" .. result .. " * (uint64_t)" .. base .. ");"
                    out[#out + 1] = indent .. "    " .. exponent .. " >>= 1;"
                    out[#out + 1] = indent .. "    " .. base .. " = (uint32_t)((uint64_t)" .. base .. " * (uint64_t)" .. base .. ");"
                    out[#out + 1] = indent .. "}"
                    out[#out + 1] = indent .. "(void)" .. result .. ";"
                elseif ins.op == "Store" then out[#out + 1] = indent .. target(ins, fn) .. " = " .. v(ins.value) .. ";"
                elseif (ins.op == "Call" or ins.op == "IndirectCall") and Model.primitive(ins.type) == "Unit" then
                    out[#out + 1] = indent .. call(ins) .. ";"
                else
                    local expression
                    if ins.op == "Div" or ins.op == "Mod" then
                        out[#out + 1] = indent .. "if (" .. v(ins.args[2]) .. " == 0) abort();"
                    end
                    if ins.op == "Constant" then expression = literal(ins.type, ins.value)
                    elseif ins.op == "Local" then expression = v(ins.initial)
                    elseif ins.op == "Load" then expression = target(ins, fn)
                    elseif ins.op == "Address" then expression = "&(" .. target(ins, fn) .. ")"
                    elseif ins.op == "Deref" then expression = v(ins.reference)
                    elseif ins.op == "Call" or ins.op == "IndirectCall" then expression = call(ins)
                    elseif ins.op == "FunctionRef" then
                        local abi = Model.callable(ins.type)
                        if abi.code then
                            expression = "(" .. ctype(ins.type) .. "){ " ..
                                (ins.receiver and (".environment = " .. (abi.value_environment and "(" or "&(") .. target(ins.receiver, fn) .. ")") or ".word_empty = 0") .. " }"
                        else
                            local environment = ins.receiver and ("&(" .. target(ins.receiver, fn) .. ")") or "NULL"
                            if ins.captures then
                                local name = "wordenv_" .. ins.id
                                out[#out + 1] = indent .. bundle(ins.target) .. " " .. name .. " = {" ..
                                    (ins.receiver and (".receiver = " .. environment .. ", ") or "") ..
                                    ".captures = " .. v(ins.captures) .. "};"
                                environment = "&" .. name
                            end
                            expression = "(" .. ctype(ins.type) .. "){.invoke = " .. adapter(ins) .. ", .environment = " .. environment .. "}"
                        end
                    elseif ins.op == "Compare" then
                        local operator = ({eq = "==", lt = "<", le = "<="})[ins.predicate]
                        expression = v(ins.args[1]) .. " " .. operator .. " " .. v(ins.args[2])
                    elseif ins.op == "Construct" or ins.op == "Capture" then
                        local fields = {}
                        for _, name in ipairs(Model.record(ins.type).runtime_order) do
                            if ins.fields[name] then fields[#fields + 1] = "." .. M.field_name(name) .. " = " .. v(ins.fields[name]) end
                        end
                        if #fields == 0 then fields[1] = ".word_empty = 0" end
                        expression = "(" .. ctype(ins.type) .. "){ " .. table.concat(fields, ", ") .. " }"
                    else
                        local operator = ({Add = "+", Sub = "-", Mul = "*", Div = "/", Mod = "%",
                            And = "&", Or = "|", Xor = "^", Shl = "<<", Shr = ">>"})[ins.op]
                        expression = "(uint32_t)((uint64_t)" .. v(ins.args[1]) .. " " .. operator .. " (uint64_t)" .. v(ins.args[2]) .. ")"
                        if ins.op == "Shl" or ins.op == "Shr" then
                            expression = "(" .. v(ins.args[2]) .. " >= UINT32_C(32) ? UINT32_C(0) : " .. expression .. ")"
                        end
                    end
                    out[#out + 1] = indent .. ctype(ins.type) .. (ins.op == "Deref" and " *" or " ") .. v(ins.id) .. " = " .. expression .. ";"
                    out[#out + 1] = indent .. "(void)" .. v(ins.id) .. ";"
                end
            end
            if tail then
                -- Borrow checking excludes arguments that could refer to this activation.
                -- Snapshot every next argument before replacing any current parameter.
                if fn.captures then
                    out[#out + 1] = indent .. ctype(fn.captures.type) .. " wordnext_captures = " .. v(tail.captures) .. ";"
                end
                for i, parameter in ipairs(fn.parameters) do
                    out[#out + 1] = indent .. ctype(parameter.type) .. " wordnext_" .. i .. " = " .. v(tail.args[i]) .. ";"
                end
                if fn.captures then out[#out + 1] = indent .. v(fn.captures.id) .. " = wordnext_captures;" end
                for i, parameter in ipairs(fn.parameters) do
                    out[#out + 1] = indent .. v(parameter.id) .. " = wordnext_" .. i .. ";"
                end
                out[#out + 1] = indent .. "continue;"
            elseif block.exit.op == "Branch" then
                out[#out + 1] = indent .. "if (" .. v(block.exit.condition) .. ") {"
                emit_block(block.exit.yes, indent .. "    ")
                out[#out + 1] = indent .. "} else {"
                emit_block(block.exit.no, indent .. "    ")
                out[#out + 1] = indent .. "}"
            else
                out[#out + 1] = block.exit.value and (indent .. "return " .. v(block.exit.value) .. ";") or indent .. "return;"
            end
        end
        if looping then out[#out + 1] = "    for (;;) {" end
        emit_block(1, looping and "        " or "    ")
        if looping then out[#out + 1] = "    }" end
        out[#out + 1] = "}"; out[#out + 1] = ""
    end
    return table.concat(out, "\n")
end

return M

end)

-- word/cli.lua
module("word.cli", function(require, ...)
-- Shared command-line behavior for wordc.lua and the single-file bundle.
-- It returns an exit status instead of exiting, so requiring this module has no side effects.
return function(Word, argv)
    local function main()
        if argv[1] == "--todos" then
            for _, item in ipairs(Word.todos()) do print(item.id .. "\t" .. item.next) end
            return
        end
        if not argv[1] or argv[2] then error("usage: luajit new/wordc.lua module.lua | --todos", 0) end
        local session = Word.new()
        local exports = session:load(argv[1])
        local function plain(t) return type(t) == "table" and getmetatable(t) == nil end
        local spec = (plain(exports.functions) or plain(exports.types) or plain(exports.results)) and exports
            or { functions = exports }
        io.write(session:emit_c(spec))
    end

    local ok, err = pcall(main)
    if ok then return 0 end
    io.stderr:write(tostring(err), "\n")
    local code = Word.is_diagnostic(err)
        and ({ reject = 1, bug = 2, todo = 3, resource = 4, lua = 1 })[err.kind]
        or 1
    return code or 1
end

end)

local Word = require('word')
local source = debug.getinfo(1, 'S').source
local script = source:sub(1, 1) == '@' and source:sub(2) or source
if arg and arg[0] == script then
    os.exit(require('word.cli')(Word, arg))
end
return Word
